/**
 * Legacy Paged.js corpus inventory. Paths stay relative to repository root.
 * Inputs copied from upstream pagedjs/specs; see ATTRIBUTION.md.
 */
export interface CaptureVariance {
	/** Exact reviewed values. Any other flow/DOM mismatch fails capture. */
	expectedFlowTotal: number;
	expectedDomPageCount: number;
	/** Count assertion source when legacy Paged.js event and DOM intentionally disagree. */
	expectedPageCountSource: "flowTotal" | "domPageCount";
}

interface LegacyFixtureBase {
	id: string;
	originalSourcePaths: readonly string[];
	copiedInputHtmlPath: string;
	copiedStylePaths: readonly string[];
	copiedAssetPaths: readonly string[];
	featureTags: readonly string[];
	expectedPageCount: number | null;
	/** Upstream assertion retained when baseline browser has an intentional difference. */
	legacyExpectedPageCount?: number;
	expectedPageCountReason?: string;
	visualTolerance: number;
	browserVariance: string;
	intentionalDifference: string | null;
	sourceEvidence?: string;
}

/** Only reviewed legacy fixture with flow metadata differing from rendered DOM. */
type FootnotesLastPageFixture = LegacyFixtureBase & {
	id: "notes/footnotes-lastpage/footnotes-lastpage";
	captureVariance: CaptureVariance;
};

export type LegacyFixture =
	(LegacyFixtureBase & { captureVariance?: never }) | FootnotesLastPageFixture;

const fixture = (record: LegacyFixture): LegacyFixture => record;

